function chart(points){if(points.length<2)return empty('Histórico comparável insuficiente para este indicador.');const W=600,H=176,x0=47,x1=582,y0=12,y1=148;const X=i=>x0+i*(x1-x0)/(points.length-1),Y=v=>y1-Math.max(0,Math.min(100,v))*(y1-y0)/100;const coords=points.map((p,i)=>X(i)+','+Y(p.y)).join(' '),last=points.at(-1),first=points[0],delta=last.y-first.y;return '<div class="ux-chart"><div class="ux-chart-summary"><strong>'+esc(pct(last.y))+'</strong><span>'+esc((delta>0?'+':'')+delta.toLocaleString('pt-BR',{maximumFractionDigits:2}))+' p.p. no período</span></div><svg class="chart ux-chart-svg" viewBox="0 0 600 176" role="img" aria-label="Evolução percentual de '+esc(pct(first.y))+' a '+esc(pct(last.y))+'">'+[0,25,50,75,100].map(v=>'<line x1="'+x0+'" y1="'+Y(v)+'" x2="'+x1+'" y2="'+Y(v)+'"/><text x="40" y="'+(Y(v)+4)+'" text-anchor="end">'+v+'%</text>').join('')+'<polyline vector-effect="non-scaling-stroke" points="'+coords+'"/><circle cx="'+X(0)+'" cy="'+Y(first.y)+'" r="3"/><circle cx="'+X(points.length-1)+'" cy="'+Y(last.y)+'" r="4"/></svg><div class="ux-chart-dates"><span>'+esc(date(first.x))+'</span><span>'+esc(date(last.x))+'</span></div><small>'+points.length+' registros comparáveis · AF-Previsão 1.3</small></div>'}
function series(n,k){const key=k+'_pct', rounds=new Map();for(const s of (data.history?.snapshots||[]).filter(s=>s.versao_modelo===data.prob?.versao_modelo&&s.hash_snapshot&&Number.isInteger(s.rodada_referencia)).sort((a,b)=>a.gerado_em.localeCompare(b.gerado_em))){const y=s.clubes?.find(c=>c.clube===n)?.[key];if(Number.isFinite(y))rounds.set(s.rodada_referencia,{x:s.gerado_em,y,round:s.rodada_referencia})}return [...rounds.values()].sort((a,b)=>a.round-b.round)}
