function probChip(c,k){const d=c.probabilidades_detalhes?.[k],label=probability(c,k),reason=d?.motivo_certeza||d?.motivo_impossibilidade||'',original=d?.exibicao??'—';return '<span class="heat-cell" data-indicator="'+k+'" data-level="'+probLevel(c,k)+'" data-source="'+esc(original)+'" title="'+esc(indicators[k]+': '+original+(Number.isFinite(d?.percentual_estimado)?' · '+d.percentual_estimado.toLocaleString('pt-BR',{maximumFractionDigits:8})+'%':'')+(reason?' · '+reason:''))+'">'+esc(label)+'</span>'}
function prob(){
 const p=data.prob,rows=[...p.clubes].sort((a,b)=>{if(state.sort==='position')return a.posicao_atual-b.posicao_atual;let x=val(a,state.indicator),y=val(b,state.indicator);if(x===null)return y===null?0:1;if(y===null)return -1;return (state.sort==='desc'?y-x:x-y)||a.posicao_atual-b.posicao_atual});
 const chosen=p.clubes.find(c=>c.clube===state.detail),move=biggestMove(state.indicator);
 const controls='<div class="r1-prob-heading"><h2>Probabilidades</h2><span class="subtle">'+esc(p.versao_modelo)+'</span></div><div class="controls r1-prob-controls"><div class="r1-prob-mode">'+pill('Compacta','view','compact',state.view==='compact')+pill('Comparativa','view','compare',state.view==='compare')+pill('Visão rápida','view','quick',state.view==='quick')+'</div><div class="r1-prob-filters">'+select('Indicador','indicator',Object.entries(indicators),state.indicator)+select('Ordenação','sort',[['position','Posição atual'],['desc','Maior chance'],['asc','Menor chance']],state.sort)+'</div></div>';
 const legend='<details id="r1-prob-legend" class="r1-prob-legend"><summary>ⓘ Como interpretar os indicadores</summary><div class="hf-legend"><span><strong>0%</strong> impossível matematicamente</span><span><strong>100%</strong> garantido matematicamente</span><span>Intensidade da cor = chance estimada; valores arredondados para leitura. ~0% / ~100% não são certezas matemáticas. Passe o cursor ou consulte o Raio-X para a fonte.</span><span>G4/G6 = terminar entre os 4/6 primeiros, não equivalem às vagas continentais finais.</span></div></details>';
 const btn=c=>'<button class="rank-button" data-action="detail" data-value="'+esc(c.clube)+'" aria-expanded="'+(state.detail===c.clube)+'">'+team(c.clube)+probChip(c,state.indicator)+'<span class="bar" data-indicator="'+state.indicator+'"><span style="width:'+Math.max(0,Math.min(100,val(c,state.indicator)??0))+'%"></span></span></button>';
 const row=c=>'<div class="rank-row">'+btn(c)+(state.detail===c.clube?'<div class="inline-detail">'+detail(c)+'</div>':'')+'</div>';
 const sidebar='<aside class="panel desktop-detail"><p class="eyebrow">'+(chosen?'Detalhe do clube':'Evolução recente')+'</p><h2>'+esc(chosen?.clube||indicators[state.indicator])+'</h2>'+(chosen?detail(chosen):'<div class="detail">'+(move?'<p>'+esc(move.name)+' · '+(move.delta>=0?'+':'')+move.delta.toLocaleString('pt-BR',{maximumFractionDigits:2})+' p.p.</p><small>R'+move.a.round+' → R'+move.b.round+' · '+esc(date(move.b.x))+'</small>':'<p>Sem snapshots comparáveis.</p>')+'</div><p class="muted">Selecione um clube para ver as vias de classificação e o histórico.</p>')+'</aside>';
 const pos=c=>'<span class="hf-pos">'+num(c.posicao_atual)+'</span>';
 const comp='<p class="hf-scroll-hint">↔ Deslize para ver mais indicadores.</p><div class="hf-table-scroll" tabindex="0" role="region" aria-label="Tabela comparativa com rolagem horizontal"><table class="matrix hf-matrix" aria-label="Comparação de probabilidades"><colgroup><col class="hf-club-col"><col class="hf-num-col"><col class="hf-num-col">'+Object.keys(indicators).map(()=>'<col class="hf-prob-col">').join('')+'<col class="hf-proj-col"><col class="hf-range-col"></colgroup><thead><tr><th scope="col" class="hf-sticky">Pos. / Clube</th><th scope="col">Pts</th><th scope="col">J</th>'+Object.keys(indicators).map(k=>'<th scope="col" data-indicator="'+k+'">'+esc(indicators[k])+'</th>').join('')+'<th scope="col">Proj.</th><th scope="col">Faixa</th></tr></thead><tbody>'+rows.map(c=>'<tr data-prob-club="'+esc(c.clube)+'"><th scope="row" class="hf-sticky"><button class="hf-club-button" data-action="detail" data-value="'+esc(c.clube)+'" aria-expanded="'+(state.detail===c.clube)+'">'+pos(c)+team(c.clube)+'<span class="hf-chevron" aria-hidden="true">⌄</span></button></th><td class="hf-points">'+num(c.pontos_atuais)+'</td><td>'+num(c.jogos_atuais)+'</td>'+Object.keys(indicators).map(k=>'<td>'+probChip(c,k)+'</td>').join('')+'<td class="hf-projection">'+(Number.isFinite(c.posicao_projetada)?num(c.posicao_projetada)+'º':'—')+'</td><td class="hf-range">'+(c.faixa_posicao_80?num(c.faixa_posicao_80.melhor)+'º–'+num(c.faixa_posicao_80.pior)+'º':'—')+'</td></tr>'+(state.detail===c.clube?'<tr class="ux-comparative-detail"><td colspan="12"><div id="hf-prob-detail">'+detail(c)+'</div></td></tr>':'')).join('')+'</tbody></table></div>';
 const methodPanel='<details id="r1-prob-method"><summary>Metodologia e certezas estruturais</summary>'+method()+'<p class="muted">As probabilidades-base são faixas de classificação de referência do modelo, mantidas nos dados originais. As colunas Libertadores e Sul-Americana incluem as vias e redistribuições aplicáveis. Vias podem ter interseção; não somar percentuais indiscriminadamente. Arredondamento apenas na interface; o valor publicado permanece disponível no detalhe do indicador. Nulos são “—”. Faixa = intervalo dos percentis 10 e 90 da posição simulada.</p><a href="estatisticas.html#more/method">Metodologia completa</a></details>';
 const compact='<div class="hf-table-scroll r1-compact-scroll"><table class="table r1-compact" aria-label="Probabilidades por indicador"><colgroup><col class="r1-club-col"><col class="r1-pts-col"><col class="r1-indicator-col"></colgroup><thead><tr><th scope="col">Pos. / Clube</th><th scope="col">Pts</th><th scope="col" data-indicator="'+state.indicator+'" title="'+esc(indicators[state.indicator])+'" aria-label="'+esc('Chance: '+indicators[state.indicator])+'">Chance</th></tr></thead><tbody>'+rows.map(c=>'<tr data-prob-club="'+esc(c.clube)+'"><th scope="row"><button class="hf-club-button" data-action="detail" data-value="'+esc(c.clube)+'" aria-expanded="'+(state.detail===c.clube)+'">'+pos(c)+team(c.clube)+'</button></th><td class="hf-points">'+num(c.pontos_atuais)+'</td><td>'+probChip(c,state.indicator)+'</td></tr>'+(state.detail===c.clube?'<tr class="r1-detail-row"><td colspan="3" id="hf-prob-detail">'+detail(c)+'</td></tr>':'')).join('')+'</tbody></table></div>';
 return state.view==='quick'?'<div class="split"><section class="panel hf-prob-panel">'+controls+rows.map(row).join('')+legend+methodPanel+'</section>'+sidebar+'</div>':'<section class="panel hf-prob-panel">'+controls+(state.view==='compact'?compact:comp)+legend+methodPanel+'</section>'
}
function aggregate(recorte, overrides){let table=data.table.tabela.map(t=>({time:t.time,pontos:0,jogos:0,vitorias:0,empates:0,derrotas:0,gp:0,gc:0,sg:0,aproveitamento:0}));let games=data.results.resultados.filter(g=>g.estado==='post'&&Number.isFinite(g.placar_mandante)&&Number.isFinite(g.placar_visitante));if(overrides)games=games.concat(data.games.jogos.filter(g=>overrides[g.event_id]?.every(x=>Number.isInteger(x)&&x>=0)).map(g=>({...g,placar_mandante:overrides[g.event_id][0],placar_visitante:overrides[g.event_id][1]})));for(const t of table){let rows=games.filter(g=>[g.mandante.nome,g.visitante.nome].includes(t.time));if(recorte==='turno')rows=rows.filter(g=>g.rodada<=19);if(recorte==='returno')rows=rows.filter(g=>g.rodada>19);if(recorte==='mandante')rows=rows.filter(g=>g.mandante.nome===t.time);if(recorte==='visitante')rows=rows.filter(g=>g.visitante.nome===t.time);if(recorte==='last5'||recorte==='last10')rows=rows.sort((a,b)=>String(a.finalizado_em||a.data_iso).localeCompare(String(b.finalizado_em||b.data_iso))).slice(recorte==='last5'?-5:-10);for(const g of rows){let h=g.mandante.nome===t.time,a=h?g.placar_mandante:g.placar_visitante,b=h?g.placar_visitante:g.placar_mandante;t.jogos++;t.gp+=a;t.gc+=b;if(a>b){t.vitorias++;t.pontos+=3}else if(a===b){t.empates++;t.pontos++}else t.derrotas++}t.sg=t.gp-t.gc;t.aproveitamento=t.jogos?Math.round(100*t.pontos/(3*t.jogos)):null}return table.sort((a,b)=>b.pontos-a.pontos||b.vitorias-a.vitorias||b.sg-a.sg||b.gp-a.gp||a.time.localeCompare(b.time,'pt-BR')).map((t,i)=>({...t,pos:i+1}))}
function tableMarkup(rows,expand=true){const fields=[['pontos','Pts'],['jogos','J'],['vitorias','V'],['empates','E'],['derrotas','D'],['gp','GP'],['gc','GC'],['sg','SG'],['aproveitamento','Aprov.']];return '<p class="hf-scroll-hint">↔ Deslize para ver todas as colunas. Pos. / Clube permanece fixo.</p><div class="hf-table-scroll" tabindex="0" role="region" aria-label="Classificação completa com rolagem horizontal"><table class="table hf-standings" aria-label="Classificação"><colgroup><col class="hf-club-col">'+fields.map(()=>'<col class="hf-num-col">').join('')+'</colgroup><thead><tr><th scope="col" class="hf-sticky">Pos. / Clube</th>'+fields.map(([k,label])=>'<th scope="col" data-field="'+k+'">'+label+'</th>').join('')+'</tr></thead><tbody>'+rows.map(t=>'<tr data-club="'+esc(t.time)+'"><th scope="row" class="hf-sticky">'+(expand?'<button class="hf-club-button" data-action="detail" data-value="'+esc(t.time)+'" aria-expanded="'+(state.detail===t.time)+'">':'<span class="hf-club-button">')+'<span class="hf-pos">'+num(t.pos)+'</span>'+team(t.time)+(expand?'<span class="hf-chevron" aria-hidden="true">⌄</span></button>':'</span>')+'</th>'+fields.map(([k])=>'<td data-field="'+k+'" '+(k==='pontos'?'class="hf-points"':'')+'>'+(k==='aproveitamento'?pct(t[k]):num(t[k]))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+(expand&&rows.some(t=>t.time===state.detail)?'<div id="hf-standings-detail">'+rows.filter(t=>t.time===state.detail).map(t=>'<div class="detail"><strong>'+esc(t.time)+'</strong> · '+num(t.pontos)+' pts · V '+num(t.vitorias)+' · E '+num(t.empates)+' · D '+num(t.derrotas)+' · GP '+num(t.gp)+' · GC '+num(t.gc)+' · SG '+num(t.sg)+' · Aproveitamento '+pct(t.aproveitamento)+form(t.time)+'<a href="'+clubLink(t.time)+'">Ver Raio-X</a></div>').join('')+'</div>':'')}
function tableView(){if(state.division==='B')return '<div class="panel"><h2>Série B · Em breve</h2>'+empty('Dados e regulamento ainda não certificados no acervo. A classificação, jogos e recortes serão habilitados somente após os gates do Plano Diretor. Sem probabilidades, live ou push.')+'</div>';let rows=state.recorte==='geral'?data.table.tabela:aggregate(state.recorte);return '<div class="panel"><div class="section-head"><div><h2>Classificação · Série A</h2><small>'+esc(fmt(data.table.atualizado_em))+' · '+esc(data.table.fonte)+'</small></div></div><div class="controls">'+[['geral','Geral'],['turno','Turno'],['returno','Returno'],['mandante','Mandante'],['visitante','Visitante'],['last5','Últimos 5'],['last10','Últimos 10']].map(([k,v])=>pill(v,'recorte',k,state.recorte===k)).join('')+'</div>'+(state.recorte==='geral'?'':notice( 'Recorte derivado dos resultados finais; turno por rodada oficial, ordem por pontos, vitórias, saldo e gols. Empates residuais ordenados por nome para leitura, sem atribuição de vaga oficial.'))+tableMarkup(rows)+'</div>'}
function performance(){let r=[...data.rank.ranking].sort((a,b)=>(b[state.perfMode]??-1)-(a[state.perfMode]??-1));return '<div class="cards">'+metric('Jogos com estatísticas',data.comp.resumo.jogos_com_estatisticas,'Cobertura publicada')+metric('Jogos com público',data.comp.resumo.jogos_com_publico,'Fonte original')+metric('Clubes',data.comp.resumo.clubes,'Série A')+'</div><div class="panel"><div class="section-head"><h2>Ranking de desempenho</h2>'+select('Métrica','perfMode',[['indice_final','Índice geral'],['ataque','Ataque'],['defesa','Defesa'],['dominio','Domínio'],['eficiencia','Eficiência'],['disciplina','Disciplina']],state.perfMode)+'</div>'+r.map(c=>'<div class="rank-row"><button class="rank-button" data-action="detail" data-value="'+esc(c.time)+'" aria-expanded="'+(state.detail===c.time)+'">'+team(c.time)+'<span class="pct">'+num(c[state.perfMode])+'</span><span class="bar"><span style="width:'+Math.max(0,Math.min(100,c[state.perfMode]??0))+'%"></span></span></button>'+(state.detail===c.time?'<div class="detail">'+esc(c.justificativa)+'<div class="fact-list">'+Object.entries(c.metricas||{}).map(([k,v])=>'<span>'+esc(k.replaceAll('_',' '))+'</span><span>'+num(v)+'</span>').join('')+'</div><a href="'+clubLink(c.time)+'">Raio-X</a></div>':'')+'</div>').join('')+'</div><div class="panel"><h2>Gols por clube</h2>'+data.comp.gols_por_clube.map(c=>'<div class="rank-row fact-list"><span>'+team(c.time)+'</span><span>'+num(c.gols_pro)+' GP · '+num(c.gols_contra)+' GC</span></div>').join('')+'</div>'+performanceCompetition()}
function performanceCompetition(){const p=data.comp.publico, highlights=data.comp.performance_por_partida||{},seq=data.comp.sequencias||{};return '<div class="panel"><h2>Campeonato · público e desempenho por jogo</h2><div class="cards">'+metric('Público total',Number(p.total_publico).toLocaleString('pt-BR'),'Jogos com público: '+p.jogos_com_publico)+metric('Público médio',Number(p.media_publico).toLocaleString('pt-BR'),'Por jogo')+metric('Renda total',Number(p.renda_total).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}),'Valores publicados')+'</div><div class="match-grid">'+Object.values(highlights).map(g=>'<article class="match"><p class="eyebrow">'+esc(g.categoria)+'</p><div class="scoreline">'+team(g.mandante)+'<span class="score">'+num(g.placar_mandante)+' – '+num(g.placar_visitante)+'</span>'+team(g.visitante)+'</div><small>R'+num(g.rodada)+' · '+esc(fmt(g.data_iso))+'</small><a href="'+esc(matchLink(g))+'">Raio-X da partida</a></article>').join('')+'</div><h3>Sequências</h3><div class="cards">'+Object.values(seq).filter(x=>x.maior).map(x=>metric(x.maior.rotulo,x.maior.time,x.maior.quantidade+' jogos')).join('')+'</div><div class="actions"><a href="estatisticas-completas.html#jogos">Estatísticas por partida (acervo original)</a><a href="estatisticas-completas.html#metodologia-ranking">Metodologia AF-Score original</a></div></div>'}
// G+A from the existing hash-verified public leader source; never fetch the internal archive.
function playerIdentity(p){const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/\s+/g,' ');return JSON.stringify([norm(p.nome),norm(p.time)])}
function participationRanking(leaders){if(leaders?.status!=='valido'||leaders.temporada!==2026||!Array.isArray(leaders.artilharia)||!Array.isArray(leaders.assistencias))throw Error('Base de gols e assistências não certificada');const map=new Map();for(const [list,field] of [['artilharia','gols'],['assistencias','assistencias']]){const seen=new Set();for(const row of leaders[list]){const key=playerIdentity(row);if(!row.nome||!row.time||!Number.isSafeInteger(row[field])||row[field]<0||seen.has(key))throw Error('Identidade ou contagem não certificada em '+list);seen.add(key);const prev=map.get(key)||{nome:row.nome,time:row.time,gols:0,assistencias:0};prev[field]=row[field];map.set(key,prev)}}return [...map.values()].map(row=>({...row,participacoes:row.gols+row.assistencias})).sort((a,b)=>b.participacoes-a.participacoes||b.gols-a.gols||b.assistencias-a.assistencias||a.nome.localeCompare(b.nome,'pt-BR')||a.time.localeCompare(b.time,'pt-BR'))}
function players(){const modes=[['artilharia','Artilharia'],['assistencias','Assistências'],['participacoes_gol','Participações em gols']],mode=state.playerMode,leaders=data.players,goal=mode==='artilharia',ass=mode==='assistencias';let source=[],sourceError='';if(goal||ass)source=leaders[mode]||[];else{try{source=participationRanking(leaders)}catch(e){sourceError=e.message}}const rows=source.map((p,i)=>({...p,rank:p.posicao??i+1})).filter(p=>!state.playerFilter||p.time===state.playerFilter),key=goal?'gols':ass?'assistencias':'participacoes',title=modes.find(x=>x[0]===mode)?.[1]||'Participações em gols';const podium=rows.slice(0,3).map((x,i)=>'<div class="ux-player-leader"><span class="ux-player-rank">'+num(x.rank)+'º</span><div><strong>'+esc(x.nome)+'</strong>'+team(x.time)+'</div><div class="ux-player-total"><strong>'+num(x[key])+'</strong><small>'+esc(goal?'gols':ass?'assist.':'G+A')+'</small></div></div>').join('');return '<section class="panel ux-players"><div class="section-head"><div><p class="eyebrow">Inteligência de jogadores</p><h2>'+esc(title)+' · Brasileirão 2026</h2><small>Base: '+esc(fmt(leaders.atualizado_em))+'</small></div><span class="ux-tag">'+rows.length+' jogadores</span></div><div class="controls ux-player-controls">'+modes.map(([k,v])=>pill(v,'playerMode',k,mode===k)).join('')+select('Clube','playerFilter',[['','Todos'],...data.clubs.clubes.map(c=>[c.nome,c.nome])],state.playerFilter)+'</div><div class="ux-player-podium">'+podium+'</div><div class="ux-player-scroll"><table class="table ux-player-table"><thead><tr><th scope="col">Pos.</th><th scope="col" class="club-cell">Jogador / clube</th>'+(goal||ass?'<th scope="col">J</th><th scope="col">'+(goal?'Gols':'Assist.')+'</th><th scope="col">/ jogo</th>':'<th scope="col">Gols</th><th scope="col">Assist.</th><th scope="col">G+A</th>')+'</tr></thead><tbody>'+rows.map(x=>'<tr><td>'+num(x.rank)+'</td><th scope="row" class="club-cell"><div class="ux-player-name"><strong>'+esc(x.nome)+'</strong>'+team(x.time)+'</div></th>'+(goal||ass?'<td>'+num(x.jogos)+'</td><td class="ux-player-primary">'+num(x[key])+'</td><td>'+ (Number.isFinite(x.media_por_jogo)?esc(x.media_por_jogo.toLocaleString('pt-BR',{maximumFractionDigits:2})):'—')+'</td>':'<td>'+num(x.gols)+'</td><td>'+num(x.assistencias)+'</td><td class="ux-player-primary">'+num(x.participacoes)+'</td>')+'</tr>').join('')+'</tbody></table></div>'+(sourceError?notice(sourceError):rows.length?'':empty('Nenhum jogador nesta seleção.'))+'<details class="ux-player-method"><summary>Fonte e metodologia</summary><p>'+esc(leaders.metodologia)+(goal||ass?'':' G+A soma os gols e as assistências das listas públicas da mesma revisão, por nome normalizado e clube; empates por gols, assistências e nome.')+'</p><p>O ranking geral AF-Player ainda não possui certificação histórica para publicação. G+A representa somente gols e assistências, não uma nota de desempenho.</p></details></section>'}
function accuracy(){let m=data.scores.metricas,a=data.acc.jogos,union=data.scores.jogos.filter(g=>g.acerto_exato||g.acerto_top3||g.acerto_ved_top1).length;return '<div class="cards">'+metric('V/E/D',pct(m.taxa_ved_top1_pct),m.acertos_ved_top1+' / '+m.previsoes_ved_top1_avaliaveis)+metric('Placar exato',pct(m.taxa_placar_exato_pct),m.placares_exatos+' / '+m.jogos)+metric('Top 3',pct(m.taxa_top3_pct),m.top3_confirmados+' / '+m.jogos)+metric('Qualquer acerto',pct(100*union/m.jogos),union+' / '+m.jogos+' · união de critérios')+'</div><div class="panel"><h2>Calibração · previsão vs frequência</h2><small>Base de V/E/D: '+num(a.jogos_avaliados)+' partidas; amostra própria, não misturar denominadores.</small><table class="table"><thead><tr><th class="club-cell">Faixa</th><th>N</th><th>Previsto</th><th>Observado</th></tr></thead><tbody>'+a.calibracao.map(c=>'<tr><td class="club-cell">'+esc(c.faixa_pct.join('–'))+'%</td><td>'+num(c.amostra)+'</td><td>'+pct(c.probabilidade_media_pct)+'</td><td>'+pct(c.frequencia_observada_pct)+'</td></tr>').join('')+'</tbody></table></div><div class="panel"><h2>Auditoria de partidas</h2><small>Somente previsões arquivadas com prova pré-jogo.</small><div class="match-grid">'+[...data.scores.jogos].reverse().map(g=>'<article class="match"><div class="match-top"><small>R'+num(g.rodada)+' · '+esc(date(g.inicio_factual))+'</small><small>'+esc([g.acerto_exato?'Exato':'',g.acerto_top3?'Top 3':'',g.acerto_ved_top1?'V/E/D':''].filter(Boolean).join(' · ')||'Sem acerto nos critérios')+'</small></div><div class="scoreline">'+team(g.mandante)+'<span class="score">'+num(g.placar_final.mandante)+' – '+num(g.placar_final.visitante)+'</span>'+team(g.visitante)+'</div><div class="fact-list"><span>Previsão modal</span><span>'+num(g.placar_modal.mandante)+' – '+num(g.placar_modal.visitante)+'</span><span>Top 3</span><span>'+g.top3_placares.map(x=>x.mandante+'–'+x.visitante).join(' / ')+'</span></div></article>').join('')+'</div></div>'}
function stats(tab){if(!tabs.some(x=>x[0]===tab))tab='prob';return '<h1 class="r1-sr-only">Estatísticas do Brasileirão 2026</h1><div class="tabs r1-stats-tabs" role="tablist" aria-label="Estatísticas">'+tabs.filter(([k])=>state.division==='A'||k==='table').map(([k,t])=>'<button id="tab-'+k+'" role="tab" aria-selected="'+(k===tab)+'" aria-controls="stats-panel" data-action="tab" data-value="'+k+'">'+esc(t)+'</button>').join('')+'</div><div class="controls r1-division">'+pill('Série A','division','A',state.division==='A')+pill('Série B · Em breve','division','B',state.division==='B')+'</div><div id="stats-panel" role="tabpanel" aria-labelledby="tab-'+tab+'">'+(state.division==='B'?tableView():({prob,table:tableView,performance,players,accuracy}[tab])())+'</div>'}
